    var START_POSTER_URI = "data:image/jpeg;base64,";
    document.getElementById("start-poster-img").src = START_POSTER_URI;

    // Position the invisible Play / Help hit-areas exactly over the icons
    // baked into the start-screen poster art (accounting for object-fit:cover
    // scaling+cropping). Poster art is 1402x1122; icon centers measured in
    // that space: Play ~ (613,172) r~55, Help ~ (760,172) r~45.
    (function(){
      // Poster art (Dinky Ink) is 1024x576; Play (green ▶) icon center measured
      // at ~(455,93), Help (?) icon center at ~(543,93) in that space.
      // Mode buttons are NOT baked into the art (free-floating UI), so they're
      // stacked entirely BELOW the Play/Help row rather than straddling above
      // and below it — anything much above cy~90 gets clipped by
      // object-fit:cover's top/bottom crop on phone screens wider than the
      // poster's 16:9 aspect (common in landscape), which is what was cutting
      // off the Frenzy button before.
      // Two columns, both top-aligned with the Play/Help row (cy:93):
      // left column (below/beside Play) = Sorted/Frenzy/5min/Variety/Levels;
      // right column (below/beside Help) = Wifi/Hammer/Walls/Open.
      var POSTER_W = 1024, POSTER_H = 576;
      var ICONS = {
        'btn-start':      { cx: 455, cy: 93 },
        'btn-start-help': { cx: 543, cy: 93 },
        // PLAY group — left column, under/beside the Play icon
        'mode-group-play':  { cx: 455 - 104, cy: 93 - 30 },
        'btn-mode-frenzy':  { cx: 455 - 104, cy: 93 },
        'btn-mode-variety': { cx: 455 - 104, cy: 93 + 34 },
        'btn-mode-sorted':  { cx: 455 - 104, cy: 93 + 68 },
        'btn-mode-3min':    { cx: 455 - 104, cy: 93 + 102 },
        // LEARN group — right column, under/beside the Help icon
        'mode-group-learn': { cx: 543 + 104, cy: 93 - 30 },
        'btn-mode-levels':  { cx: 543 + 104, cy: 93 },
        'btn-mode-walls':   { cx: 543 + 104, cy: 93 + 34 },
        'btn-mode-open':    { cx: 543 + 104, cy: 93 + 68 },
        'btn-mode-open2':   { cx: 543 + 104, cy: 93 + 102 },
        'btn-watch':        { cx: 543 + 104, cy: 93 + 136 }
      };
      function positionStartIcons(){
        var img = document.getElementById('start-poster-img');
        if (!img) return;
        var rect = img.getBoundingClientRect();
        if (!rect.width || !rect.height) return;
        var scale = Math.max(rect.width / POSTER_W, rect.height / POSTER_H);
        var dispW = POSTER_W * scale, dispH = POSTER_H * scale;
        var offX = rect.left - (dispW - rect.width) / 2;
        var offY = rect.top - (dispH - rect.height) / 2;
        Object.keys(ICONS).forEach(function(id){
          var el = document.getElementById(id);
          if (!el) return;
          var spec = ICONS[id];
          el.style.left = (offX + spec.cx * scale) + 'px';
          el.style.top = (offY + spec.cy * scale) + 'px';
        });
      }
      window.addEventListener('resize', positionStartIcons);
      window.addEventListener('load', positionStartIcons);
      document.getElementById('start-poster-img').addEventListener('load', positionStartIcons);
      positionStartIcons();
      setTimeout(positionStartIcons, 0);
    })();

    document.getElementById("btn-start-help").addEventListener("click", function(){
      document.getElementById("guide-choice-overlay").classList.add("open");
    });
    document.getElementById("btn-watch").addEventListener("click", function(){
      this.blur(); // otherwise this focused button eats the Space bar as its own "activate" key, re-triggering startWatch() (and resetting AutoPlay back on) every time the player tries to use Space as the manual/autoplay toggle
      startWatch();
    });
    document.getElementById("guide-choice-close-btn").addEventListener("click", function(){
      document.getElementById("guide-choice-overlay").classList.remove("open");
    });
    document.getElementById("guide-choice-overlay").addEventListener("click", function(e){
      if (e.target.id === "guide-choice-overlay") e.currentTarget.classList.remove("open");
    });
    document.getElementById("guide-choice-text-btn").addEventListener("click", function(){
      document.getElementById("guide-choice-overlay").classList.remove("open");
      document.getElementById("start-help-overlay").classList.add("open");
    });
    document.getElementById("guide-choice-visual-btn").addEventListener("click", function(){
      document.getElementById("guide-choice-overlay").classList.remove("open");
      if (typeof renderVisualGuide === 'function') renderVisualGuide();
      document.getElementById("visual-guide-overlay").classList.add("open");
    });
    document.getElementById("start-help-close-btn").addEventListener("click", function(){
      document.getElementById("start-help-overlay").classList.remove("open");
    });
    document.getElementById("start-help-overlay").addEventListener("click", function(e){
      if (e.target.id === "start-help-overlay") e.currentTarget.classList.remove("open");
    });
    document.getElementById("visual-guide-close-btn").addEventListener("click", function(){
      document.getElementById("visual-guide-overlay").classList.remove("open");
    });
    document.getElementById("visual-guide-back-btn").addEventListener("click", function(){
      document.getElementById("visual-guide-overlay").classList.remove("open");
      document.getElementById("guide-choice-overlay").classList.add("open");
    });
    document.getElementById("visual-guide-overlay").addEventListener("click", function(e){
      if (e.target.id === "visual-guide-overlay") e.currentTarget.classList.remove("open");
    });
